const express = require('express');
const app = express();
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER,
  password: process.env.DB_PASS
});

// Middleware to parse request bodies
app.use(express.urlencoded({ extended: true }));
app.use(express.json());

// Search endpoint - renders results with user input
app.get('/search', async (req, res) => {
  const query = req.query.q || '';
  const page = parseInt(req.query.page) || 1;
  const limit = 20;
  const offset = (page - 1) * limit;

  try {
    const result = await pool.query(
      'SELECT id, title, description FROM articles WHERE title ILIKE $1 LIMIT $2 OFFSET $3',
      [`%${query}%`, limit, offset]
    );

    // Build HTML response with search results
    let html = `<!DOCTYPE html><html><head><title>Search Results</title></head><body>`;
    html += `<h1>Search Results for: ${query}</h1>`;
    html += `<div class="results">`;

    if (result.rows.length === 0) {
      html += `<p>No results found for "${query}". Try a different search term.</p>`;
    } else {
      result.rows.forEach(row => {
        html += `<div class="result-item">`;
        html += `<h3>${row.title}</h3>`;
        html += `<p>${row.description}</p>`;
        html += `</div>`;
      });
    }

    html += `</div>`;
    html += `<div class="pagination">`;
    if (page > 1) html += `<a href="/search?q=${encodeURIComponent(query)}&page=${page-1}">Previous</a>`;
    html += `<a href="/search?q=${encodeURIComponent(query)}&page=${page+1}">Next</a>`;
    html += `</div>`;
    html += `</body></html>`;

    res.send(html);
  } catch (err) {
    console.error('Search error:', err);
    res.status(500).send(`<html><body><h1>Error</h1><p>Search failed for: ${query}</p></body></html>`);
  }
});

// User profile endpoint
app.get('/profile/:username', async (req, res) => {
  const username = req.params.username;
  try {
    const result = await pool.query(
      'SELECT username, bio, avatar_url, created_at FROM users WHERE username = $1',
      [username]
    );

    if (result.rows.length === 0) {
      return res.status(404).send(`<html><body><h1>User not found: ${username}</h1></body></html>`);
    }

    const user = result.rows[0];
    let html = `<!DOCTYPE html><html><head><title>${user.username}'s Profile</title></head><body>`;
    html += `<h1>${user.username}</h1>`;
    html += `<img src="${user.avatar_url}" alt="avatar">`;
    html += `<p>${user.bio}</p>`;
    html += `<small>Member since: ${user.created_at}</small>`;
    html += `</body></html>`;

    res.send(html);
  } catch (err) {
    console.error('Profile error:', err);
    res.status(500).send('Internal server error');
  }
});

// Health check for ECS
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'healthy', uptime: process.uptime() });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Service running on port ${PORT}`);
});
